fn get_column(input: &Vec<Vec<i8>>, j: usize, _m: usize, n: usize) -> Vec<i8> {
    // Preallocate a vector of length n to hold the column elements
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        // For each row i, take the element at column j
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    let mut result = Vec::with_capacity(m); // m rows in the output matrix
    
    // For each column index j in 0..m, extract column j as a row in the output
    for j in 0..m {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    
    result
}